const {normalize:normalizeName,classify}=require('../reporting/candidates'),links=require('../review/public/deep-links');
async function menuTarget(name='Synthetic dish'){const {r}=await recipe('2',name),id=(await f.run('createMenuItem',{name})).id;await f.run('setMenuMapping',{menuItemId:id,recipeId:r.id,quantity:'2',unit:'each',effectiveAt:early});return {id:r.id,r};}
const menuPolicy=(id,extra={})=>({recipeId:id,...extra});
test('Mapping: new identity is Needs Mapping, not unresolved cost or $0 COGS',async()=>{const a=fact({quantity:'3'});await ingest([a]);const d=await result();assert.equal(d.rows[0].status,'NEEDS_MAPPING');assert.equal(d.rows[0].total,null);assert.equal(d.rows[0].costStatus,null);assert.equal(d.summary.unmappedQuantity,'3');assert.equal(d.summary.coverage.unresolved.quantity,'0');assert.equal(d.summary.quantity,'0');assert.equal(d.reconciled,true);});
