 await measure('filterNeedsMapping',()=>ranges.queue(q.items,{status:'unmapped',scope:'recent',sort:'name',direction:'asc'}));await measure('sortUnits',()=>ranges.queue(q.items,{status:'unmapped',scope:'recent',sort:'quantity',direction:'desc'}));
 const i=q.items[0];await measure('singleConfirm',()=>svc.mappingBulk(admin,{confirmed:true,entries:[q.bulk.recent.entries[0]]}));const b=await measure('targetedRebuild',()=>svc.rebuild(admin,period));assert.equal(b.built,1);assert.equal((await svc.report(admin,period)).summary.quantity,i.quantity);
 q=await svc.mappings(admin,period);const bulk=await measure('bulk29',()=>svc.mappingBulk(admin,{confirmed:true,entries:q.bulk.recent.entries}));assert.equal(bulk.committed,29);
 await measure('ignoreOn',()=>map(i.id,r,{state:'excluded',expectedVersion:1,recipeId:null,quantity:null,unit:null}));await measure('ignoreOff',()=>map(i.id,r,{state:'unmapped',expectedVersion:2,recipeId:null,quantity:null,unit:null}));assert.equal((await svc.mappings(admin,period)).items.find(x=>x.id===i.id).state,'unmapped');console.log('Mapping fixture timings (ms): '+JSON.stringify(metrics));
