// Composite tests use the same isolated PostgreSQL and full domain costing path.
const Composite=require('../reporting/composite');
const modifier=(itemId,groupId,quantity='1',more={})=>({id:uuid(),itemId,groupId,quantity,price:'0',voided:false,type:'NONE',modifiers:[],...more});
async function compositeFixture(mix=['pork','pork','spam'],extra={}){const pork=await recipe('9','Pork plate'),burger=await recipe('12','Burger plate'),spam=await recipe('6','Spam plate'),g=uuid(),ids={pork:uuid(),burger:uuid(),spam:uuid()},a=fact({name:'Mixed plate',modifiers:mix.map(k=>modifier(ids[k],g)),...extra});await ingest([a]);const body={id:null,expectedVersion:0,confirmed:true,period,definition:{name:'Mixed sliders',pieceName:'sliders',expectedPieces:'3',components:Object.entries({pork,burger,spam}).map(([key,r])=>({key,name:key,recipeId:r.r.id,piecesPerExecution:'3'})),parents:[{itemId:a.itemId,expectedVersion:0,groupPath:[g],options:[...new Set(mix)].map(k=>({optionId:ids[k],componentKey:k}))}]}};return {a,body,pork,burger,spam,g,ids};}
for(const [name,mix,wanted,ratios]of [['three Pork',['pork','pork','pork'],'9.000000000000',{pork:['1','1']}],['two Pork one Spam',['pork','pork','spam'],'8.000000000000',{pork:['2','3'],spam:['1','3']}],['one of each',['pork','burger','spam'],'9.000000000000',{pork:['1','3'],burger:['1','3'],spam:['1','3']}]])test('Composite exact acceptance: '+name,async()=>{const {body}=await compositeFixture(mix),r=await svc.composites.preview(admin,body);assert.equal(r.saved,false);assert.equal(r.total,wanted);assert.equal(r.composition.reconciled,true);for(const [k,[n,d]]of Object.entries(ratios)){const p=r.provenance[0].parts.filter(p=>p.componentKey===k);assert.equal(p.length,1);assert.deepEqual(p[0].executions,{n,d});}assert.equal((await pool.query('SELECT count(*) FROM wahi_v2.cogs_mappings')).rows[0].count,'0');assert.equal((await pool.query('SELECT generation FROM wahi_v2.cogs_knowledge')).rows[0].generation,0);});
test('Composite: array order and duplicate occurrences canonicalize identically',async()=>{const x=await compositeFixture(),a=Composite.inspect(x.a,x.body.definition),b=Composite.inspect({...x.a,modifiers:[...x.a.modifiers].reverse()},x.body.definition);assert.equal(a.canonical,b.canonical);assert.equal(a.pieces.find(p=>p.component.key==='pork').quantity.decimal(0),'2');});
test('Composite: explicit option quantity is summed, not row count',async()=>{const x=await compositeFixture();x.a.modifiers=[modifier(x.ids.pork,x.g,'2'),modifier(x.ids.spam,x.g,'1')];await ingest([x.a]);const r=await svc.composites.preview(admin,x.body);assert.equal(r.total,'8.000000000000');assert.equal(r.composition.reconciled,true);});
test('Composite: quantity two parent with explicit child totals six is not multiplied twice',async()=>{const x=await compositeFixture();x.a.quantity='2';x.a.modifiers=[modifier(x.ids.pork,x.g,'2'),modifier(x.ids.pork,x.g,'2'),modifier(x.ids.spam,x.g,'2')];await ingest([x.a]);const r=await svc.composites.preview(admin,x.body);assert.equal(r.total,'16.000000000000');assert.equal(r.average,'8.000000000000');assert.equal(r.composition.reconciled,true);});
test('Composite: split-sale decimal thirds preserve exact parent and child quantities',async()=>{const x=await compositeFixture();x.a.quantity='0.3333333333333333';x.a.splitOrigin=uuid();x.a.modifiers=x.a.modifiers.map(m=>({...m,quantity:x.a.quantity}));await ingest([x.a]);const r=await svc.composites.preview(admin,x.body);assert.equal(r.quantity,x.a.quantity);assert.equal(r.composition.reconciled,true);const p=r.provenance[0].parts.find(p=>p.componentKey==='pork');assert.ok(require('../reporting/cost').unpack(p.executions).eq(E.of(x.a.quantity).mul('2').div('3')));});
