async function variantFixture(){const three=await recipe('9','Fish and Chips, Three'),four=await recipe('12','Fish and chips, Four'),group=uuid(),a3=uuid(),a4=uuid(),a=fact({name:'Fish and Chips',modifiers:[modifier(a3,group)]}),b=fact({itemId:a.itemId,name:a.name,modifiers:[modifier(a4,group)]});await ingest([a,b]);return {a,b,three,four,group,a3,a4,body:{id:null,expectedVersion:0,confirmed:true,period,definition:{name:'Fish variants',choices:[{key:'three',name:'3 Pieces',recipeId:three.r.id},{key:'four',name:'4 Pieces',recipeId:four.r.id}],parents:[{itemId:a.itemId,expectedVersion:0,groupPath:[group],options:[{optionId:a3,choiceKey:'three'},{optionId:a4,choiceKey:'four'}]}]}}};}
test('Variant: one 3/4 choice executes the selected complete Recipe once and preview is read-only',async()=>{const x=await variantFixture(),r=await svc.variants.preview(admin,x.body);assert.equal(r.total,'21.000000000000');assert.equal(r.quantity,'2');assert.equal(r.variant.complete,true);assert.deepEqual(r.provenance.map(p=>p.executions),[{n:'1',d:'1'},{n:'1',d:'1'}]);assert.equal((await pool.query('SELECT count(*) FROM wahi_v2.cogs_variants')).rows[0].count,'0');assert.equal((await pool.query('SELECT max(generation) n FROM wahi_v2.cogs_knowledge')).rows[0].n,0);});
