test('Variant: saved definition reloads stable identities and preserves structured provenance through renames',async()=>{const x=await variantFixture(),saved=await svc.variants.save(admin,x.body);x.a.name='Renamed';await ingest([x.a,x.b]);await result();const fresh=new TrueCogs(pool,{}, {clock:()=>Date.parse(now)}),r=await fresh.detail(manager,{...period,id:x.a.itemId});assert.equal(r.variant.resolved,'2.00000000000000000000');assert.equal(r.days[0].payload.target.variantId,saved.id);const p=(await pool.query('SELECT payload FROM wahi_v2.cogs_knowledge')).rows[0].payload;assert.equal(p.variants[0].optionId,x.a3);assert.deepEqual(p.variants[0].executions,{n:'1',d:'1'});});
test('Variant: future unknown option retains old costs, revenue and historical option mappings',async()=>{const x=await variantFixture(),saved=await svc.variants.save(admin,x.body),future=uuid(),c=fact({itemId:x.a.itemId,modifiers:[modifier(future,x.group)]});await pool.query("INSERT INTO wahi_v2.cogs_choice_labels VALUES($1,'2 Pieces','option',CURRENT_TIMESTAMP)",[future]);await ingest([x.a,x.b,c]);const r=await result();assert.equal(r.summary.total,'21.000000000000');assert.equal(r.summary.netSales,'30.000000000000');assert.equal(r.summary.coverage.unresolved.quantity,'1');assert.equal(r.rows[0].variant.warnings[0].name,'2 Pieces');assert.equal(r.rows[0].variant.reconciled,true);const q=await svc.mappings(admin,period);assert.equal(q.items[0].state,'mapped');assert.equal(q.items[0].definitionStatus,'Needs Attention');assert.equal(q.coverage.unitsPercent,'66.67');const d=(await svc.variants.catalog(admin,{id:x.a.itemId})).definitions.find(d=>d.id===saved.id);assert.equal(d.definition.parents[0].options.length,2);x.body.id=saved.id;x.body.expectedVersion=1;x.body.definition.parents[0].expectedVersion=1;x.body.definition.parents[0].options.push({optionId:future,choiceKey:'three'});await svc.variants.save(admin,x.body);assert.equal((await result()).summary.total,'30.000000000000');});
