test('Variant: missing Recipe cost is separate from complete mapping',async()=>{const x=await variantFixture(),bad=await f.recipe('No yield',[{ingredientId:x.three.p.id,quantity:'1',unit:'each'}],null,null);await eligible(bad);x.body.definition.choices[1].recipeId=bad.id;await svc.variants.save(admin,x.body);const r=await result();assert.equal(r.status,undefined);assert.equal(r.rows[0].status,'UNRESOLVED');assert.equal(r.rows[0].actionRequired,false);assert.equal(r.summary.mappingCoverage.mapped,'100.00');assert.equal((await svc.mappings(admin,period)).items[0].definitionStatus,'Complete');});
test('Variant: targeted invalidation and append-only history preserve facts and unrelated Simple costs',async()=>{const x=await variantFixture(),c=fact();await ingest([x.a,x.b,c]);await map(c.itemId,x.three.r);const saved=await svc.variants.save(admin,x.body);await result();const before=(await pool.query('SELECT source FROM wahi_v2.sales_facts ORDER BY id')).rows;x.body.id=saved.id;x.body.expectedVersion=1;x.body.definition.parents[0].expectedVersion=1;x.body.definition.choices[0].recipeId=x.four.r.id;await svc.variants.save(admin,x.body);assert.deepEqual((await pool.query('SELECT item_id FROM wahi_v2.cogs_knowledge WHERE dirty')).rows.map(r=>r.item_id),[x.a.itemId]);assert.equal((await result()).rows.find(r=>r.id===x.a.itemId).total,'24.000000000000');assert.deepEqual((await pool.query('SELECT source FROM wahi_v2.sales_facts ORDER BY id')).rows,before);assert.equal((await svc.mappingHistory(admin,{id:x.a.itemId})).variantEvents.length,2);await assert.rejects(pool.query('DELETE FROM wahi_v2.cogs_variant_audit'));});
test('Variant: parent Ignore detaches definition and preserves audit',async()=>{const x=await variantFixture(),s=await svc.variants.save(admin,x.body);await svc.mapping(admin,{itemId:x.a.itemId,state:'excluded',expectedVersion:1,recipeId:null,confirmed:true});assert.equal((await pool.query('SELECT definition FROM wahi_v2.cogs_variants WHERE id=$1',[s.id])).rows[0].definition.parents.length,0);assert.equal((await pool.query('SELECT variant_id FROM wahi_v2.cogs_mappings')).rows[0].variant_id,null);});
test('Variant: Admin only writes, Manager reads, Staff/Lead denied and stale versions rejected',async()=>{const x=await variantFixture();for(const actor of [manager,staff,lead]){await assert.rejects(svc.variants.preview(actor,x.body));await assert.rejects(svc.variants.save(actor,x.body));await assert.rejects(svc.variants.catalog(actor,{id:x.a.itemId}));}const saved=await svc.variants.save(admin,x.body);await result();assert.equal((await svc.report(manager,period)).summary.total,'21.000000000000');for(const actor of [staff,lead])await assert.rejects(svc.detail(actor,{...period,id:x.a.itemId}));await assert.rejects(svc.variants.save(admin,{...x.body,id:saved.id}));});
test('Variant: eligible categories and valid observed identities enforced',async()=>{const x=await variantFixture();for(const mutate of [b=>b.definition.parents[0].groupPath=[uuid()],b=>b.definition.parents[0].options[0].optionId=uuid(),b=>b.definition.parents[0].options.push(b.definition.parents[0].options[0])]){const b=structuredClone(x.body);mutate(b);await assert.rejects(svc.variants.save(admin,b));}await settings([]);await assert.rejects(svc.variants.preview(admin,x.body));});
test('Variant: 500 sales share cached cost resolution and repeat views read materialized knowledge',async()=>{const x=await variantFixture(),rows=Array.from({length:500},(_,i)=>fact({itemId:x.a.itemId,modifiers:[modifier(i%2?x.a3:x.a4,x.group)]}));await ingest(rows);const t=performance.now(),p=await svc.variants.preview(admin,x.body),previewMs=performance.now()-t,t2=performance.now();assert.equal(p.stats.historicalResolutions,2);await svc.variants.save(admin,x.body);const saveMs=performance.now()-t2,b=await svc.rebuild(admin,period),r=await svc.report(manager,period);assert.equal(r.summary.total,'5250.000000000000');assert.equal(r.stats.historicalResolutions,0);console.log('Variant fixture performance',{previewMs,saveMs,recalculationMs:b.stats.durationMs,repeatMs:r.stats.durationMs});});
test('Variant: changing a dependent Recipe cost invalidates only its materialized parent',async()=>{const x=await variantFixture();await svc.variants.save(admin,x.body);await result();await f.run('addPrice',{purchaseOptionId:x.three.p.option,amount:'18',currency:'USD',effectiveAt:day+'T00:00:00Z'});assert.equal((await svc.report(manager,period)).dirtyRows,1);assert.equal((await result()).summary.total,'30.000000000000');});
test('Queue UX: modal closes without save and returns focus/position; save keeps next row and filters',async()=>{const vm=require('node:vm'),source=await fs.readFile(path.join(__dirname,'../review/public/mapping-ui.js'),'utf8');let focused,scrolls=[],rendered=false;const action=id=>({focus:()=>focused=id}),row=(id,top)=>({dataset:{mappingRow:id},getBoundingClientRect:()=>({top}),querySelector:()=>action(id)});let rows=[row('a',200),row('b',250)],dialog={open:false,showModal(){this.open=true;},close(){this.open=false;}};const ctx=vm.createContext({document:{querySelectorAll:()=>rows},window:{scrollY:600,scrollBy:(x,y)=>scrolls.push(y),scrollTo(){},confirm:()=>true},$:()=>dialog});vm.runInContext(source,ctx);vm.runInContext("mappingFilters={search:'fish',status:'unmapped',quality:'CHOICES',scope:'all',sort:'quantity',direction:'desc'};mappingRemember({id:'a'},{dataset:{mappingAction:'variant'}});mappingOpen({id:'a'});mappingClose();",ctx);assert.equal(dialog.open,false);assert.equal(focused,'a');ctx.rerender=()=>{rendered=true;rows=[row('b',200)];};await vm.runInContext("cogsMappingPage=async preserve=>{if(!preserve)throw Error('context lost');rerender();};refreshMappingBadge=async()=>{};mappingFinished()",ctx);assert.equal(rendered,true);assert.equal(focused,'b');assert.equal(scrolls.at(-1),0);assert.equal(vm.runInContext('mappingFilters.search',ctx),'fish');assert.equal(vm.runInContext('mappingFilters.sort',ctx),'quantity');});
test('Queue UX: Escape discard warning preserves meaningful edits when declined',async()=>{const vm=require('node:vm'),source=await fs.readFile(path.join(__dirname,'../review/public/mapping-ui.js'),'utf8');const d={open:true,close(){this.open=false;}},ctx=vm.createContext({window:{confirm:()=>false},$:()=>d});vm.runInContext(source,ctx);vm.runInContext('mappingDirty=true;mappingClose()',ctx);assert.equal(d.open,true);});
test('Queue UX: searchable Variant suggestions never guess ambiguous Recipe targets',async()=>{const vm=require('node:vm'),source=await fs.readFile(path.join(__dirname,'../review/public/variant-ui.js'),'utf8'),ctx=vm.createContext({});vm.runInContext(source,ctx);assert.equal(vm.runInContext("variantSuggestion('Fish and Chips','3 Pieces',[{id:'three',name:'Fish and Chips, Three'}])",ctx),'three');assert.equal(vm.runInContext("variantSuggestion('Fish and Chips','3 Pieces',[{id:'three',name:'Fish and Chips, Three'},{id:'other',name:'Fish and Chips, Three'}])",ctx),'');assert.doesNotMatch(source,/piecesPerExecution|name="quantity"|name="unit"/);});
test('Queue UX: neutral choices are manually mappable and details remain inside separated records',async()=>{const html=await fs.readFile(path.join(__dirname,'../review/public/mapping-ui.js'),'utf8'),css=await fs.readFile(path.join(__dirname,'../review/public/style.css'),'utf8');assert.match(html,/CHOICES:'Recipe-Defining Choices'/);assert.doesNotMatch(html,/Potential Composite/);assert.match(html,/data-mapping-action="variant"/);assert.match(html,/data-mapping-action="composite"/);assert.match(html,/<dialog id="mapping-dialog"/);assert.match(html,/<tr data-mapping-row=.*?<details>/);assert.match(css,/#mapping-table tbody > tr \+ tr > th/);assert.match(html,/mapping-dialog'\)\.addEventListener\('cancel'/);});
test('Variant: disabling eligible category retains existing historical option targets on edit',async()=>{const x=await variantFixture(),s=await svc.variants.save(admin,x.body);await settings([]);x.body.id=s.id;x.body.expectedVersion=1;x.body.definition.parents[0].expectedVersion=1;x.body.definition.name='Updated label';await svc.variants.save(admin,x.body);assert.equal((await result()).summary.total,'21.000000000000');});
test('Variant: moving a parent to Composite removes stale Variant binding',async()=>{const x=await variantFixture(),saved=await svc.variants.save(admin,x.body),body={id:null,expectedVersion:0,confirmed:true,period,definition:{name:'Explicit composite',pieceName:'choices',expectedPieces:'1',components:[{key:'a',name:'a',recipeId:x.three.r.id,piecesPerExecution:'1'},{key:'b',name:'b',recipeId:x.four.r.id,piecesPerExecution:'1'}],parents:[{itemId:x.a.itemId,expectedVersion:1,groupPath:[x.group],options:[{optionId:x.a3,componentKey:'a'},{optionId:x.a4,componentKey:'b'}]}]}};await svc.composites.save(admin,body);assert.equal((await pool.query('SELECT definition FROM wahi_v2.cogs_variants WHERE id=$1',[saved.id])).rows[0].definition.parents.length,0);assert.equal((await result()).summary.total,'21.000000000000');});
